from collections import Counter,deque

def transform2(grid):
 h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]; out=[[bg]*w for _ in range(h)]; seen=set()
 for r in range(h):
  for c in range(w):
   col=grid[r][c]
   if col==bg or (r,c) in seen: continue
   q=deque([(r,c)]);seen.add((r,c)); comp=[]
   while q:
    y,x=q.popleft();comp.append((y,x))
    for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
     if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==col:
      seen.add((yy,xx));q.append((yy,xx))
   ys=[y for y,x in comp];xs=[x for y,x in comp]; y0,y1=min(ys),max(ys);x0,x1=min(xs),max(xs); area=(y1-y0+1)*(x1-x0+1)
   if y1>y0 and x1>x0 and len(comp)/area>=.5:
    for y in range(y0,y1+1):
     for x in range(x0,x1+1):out[y][x]=col
 return out
